INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31011, 'Matthew 23:8', 'Matthew', 23, 8, 'خو تاسو ته باید ‹استاذ› ونه ویل شي، ځکه چې تاسو یوازې یو استاذ لرئ او تاسو ټول سره ورونه یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_8.mp3', '', 1761754199, 1761754199),
(31012, 'Matthew 23:9', 'Matthew', 23, 9, 'په دې نړۍ کې هېچا ته ‹پلار› مه وایئ، ځکه چې تاسو یوازې یو پلار لرئ چې هغه په اسمان کې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_9.mp3', '', 1761754199, 1761754199),
(31013, 'Matthew 23:10', 'Matthew', 23, 10, 'نه دې څوک درته ‹لارښوونکی› ووایي، ځکه چې تاسو یوازې یو لارښوونکی لرئ چې هغه مسیح دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_10.mp3', '', 1761754199, 1761754199),
(31014, 'Matthew 23:11', 'Matthew', 23, 11, 'په تاسو کې هغه څوک د ټولو نه لوی دی چې ستاسو خدمتګار وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_11.mp3', '', 1761754199, 1761754199),
(31015, 'Matthew 23:12', 'Matthew', 23, 12, 'ځکه هرڅوک چې خپل ځان لوی ګڼي هغه به عاجز شي او هرڅوک چې خپل ځان عاجز کړي هغه به سرلوړی شي.» د مذهبي مشرانو منافقت (مرقوس ۱۲‏:‌۴۰ او لوقا ۱۱‏:‌۳۹‌‏-‌۴۲، ۱۱‏:‌۴۴، ۱۱‏:‌۵۲، ۲۰‏:‌۴۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_12.mp3', '', 1761754199, 1761754199),
(31016, 'Matthew 23:13', 'Matthew', 23, 13, 'عیسی زیاته کړه: «ای منافقانو د شریعت عالمانو او فریسیانو! ستاسو په حال دې افسوس وي، ځکه چې تاسو د اسماني پاچاهۍ دروازې د خلکو دپاره بندوئ، نه تاسو ورننوځئ او نه نور خلک پرېږدئ چې ورننوځي. [', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_13.mp3', '', 1761754199, 1761754199),
(31017, 'Matthew 23:14', 'Matthew', 23, 14, 'ای منافقانو د شریعت عالمانو او فریسیانو! ستاسو په حال دې افسوس وي، ځکه چې تاسو د کونډو مالونه خورئ، خو د ځان ښودنې دپاره اوږدې اوږدې دعاګانې کوئ، خو خدای به تاسو ته د نورو څخه سخته سزا درکړي.]', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_14.mp3', '', 1761754199, 1761754199),
(31018, 'Matthew 23:15', 'Matthew', 23, 15, 'ای منافقانو د شریعت عالمانو او فریسیانو! ستاسو په حال دې افسوس وي، ځکه چې تاسو په وچه او اوبو کې ګرځئ چې کوم څوک خپل دین ته راواړوئ او کله چې ستاسو دین قبول کړي، نو هغه ستاسو څخه دوه چنده د دوزخ د سزا وړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_15.mp3', '', 1761754199, 1761754199),
(31019, 'Matthew 23:16', 'Matthew', 23, 16, 'افسوس دې وي په تاسو باندې ای د ړندو لارښوونکو! تاسو وایئ: ‹که چېرې څوک د خدای د کور په نوم قسم وخوري، نو هېڅ خبره نه ده، خو که څوک د خدای د کور په سرو زرو قسم وخوري، نو هغه مجبور دی چې په خپل قسم ولاړ اوسي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_16.mp3', '', 1761754199, 1761754199),
(31020, 'Matthew 23:17', 'Matthew', 23, 17, 'ای کم‌عقلو ړندو! کوم یو یې مهم دی، سره زر یا د خدای کور چې سره زر پاک او سپېڅلي کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_17.mp3', '', 1761754199, 1761754199),
(31021, 'Matthew 23:18', 'Matthew', 23, 18, 'همدارنګه تاسو وایئ: ‹که چېرې څوک د قربانۍ د ځای په نوم قسم وخوري، نو هېڅ خبره نه ده، خو که څوک د قربانۍ د ځای په نذرانې قسم وخوري، نو هغه مجبور دی چې په خپل قسم ولاړ اوسي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_18.mp3', '', 1761754199, 1761754199),
(31022, 'Matthew 23:19', 'Matthew', 23, 19, 'ای ړندو خلکو! کوم یو یې مهم دی، نذرانه یا د قربانۍ ځای چې هغه نذرانه پاک او سپېڅلې کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_19.mp3', '', 1761754199, 1761754199),
(31023, 'Matthew 23:20', 'Matthew', 23, 20, 'نو څوک چې د قربانۍ په ځای قسم خوري، هغه د قربانۍ په ځای او په کومو سوغاتونو چې خلکو هلته ایښي دي قسم خوري،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_20.mp3', '', 1761754199, 1761754199),
(31024, 'Matthew 23:21', 'Matthew', 23, 21, 'او څوک چې د خدای د کور په نوم قسم خوري، نو د خدای په کور او خدای باندې چې په هغه کې اوسیږي قسم خوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_21.mp3', '', 1761754199, 1761754199),
(31025, 'Matthew 23:22', 'Matthew', 23, 22, 'څوک چې په اسمان باندې قسم خوري، نو هغه د خدای په تخت او هغه چا باندې قسم خوري چې په هغه تخت باندې کښېني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_22.mp3', '', 1761754199, 1761754199),
(31026, 'Matthew 23:23', 'Matthew', 23, 23, 'ای منافقانو د شریعت عالمانو او فریسیانو! ستاسو په حال دې افسوس وي، ځکه چې تاسو د وېلني، شبت او زنکۍ لسمه برخه ورکوئ، خو د شریعت ډېر مهم حکمونه لکه عدالت، رحم او وفاداري مو پریښي دي. تاسو باید په دې ټولو باندې عمل کولای او هغه نور مو هم له پامه نه غورځولی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_23.mp3', '', 1761754199, 1761754199),
(31027, 'Matthew 23:24', 'Matthew', 23, 24, 'ای ړندو لارښوونکو! تاسو ماشی د اوبو څخه لېرې کوئ، خو اوښ لواړ تېروئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_24.mp3', '', 1761754199, 1761754199),
(31028, 'Matthew 23:25', 'Matthew', 23, 25, 'ای منافقانو د شریعت عالمانو او فریسیانو! افسوس دې وي ستاسو په حال باندې، ځکه چې تاسو د خپلو پیالو او قابونو باندینۍ برخې پاکوئ خو دننه یې د هغو شیانو څخه ډک دي چې په حرص او ځان غوښتنې مو ګټلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_25.mp3', '', 1761754199, 1761754199),
(31029, 'Matthew 23:26', 'Matthew', 23, 26, 'ای ړندو فریسیانو! لومړی د پیالو او قابونو دنننی برخه پاکه کړئ، نو باندینۍ برخه به یې هم پاکه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_26.mp3', '', 1761754199, 1761754199),
(31030, 'Matthew 23:27', 'Matthew', 23, 27, 'ای منافقانو د شریعت عالمانو او فریسیانو! افسوس دې وي ستاسو په حال باندې، ځکه چې تاسو د هغو قبرونو په شان یئ چې په چونه باندې سپین شوي وي چې په ظاهره ښکلي ښکاري، خو دننه د مړو د هډوکو او هر ډول ناپاکیو څخه ډک وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_27.mp3', '', 1761754199, 1761754199),
(31031, 'Matthew 23:28', 'Matthew', 23, 28, 'نو په همدې ډول تاسو هم په ښکاره نېک خلک ښکارئ، خو دننه د منافقت او بدیو څخه ډک یئ.» عیسی د مذهبي مشرانو د سزا پېشګويي کوي (لوقا ۱۱‏:‌۴۷‌‏-‌۵۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_28.mp3', '', 1761754199, 1761754199),
(31032, 'Matthew 23:29', 'Matthew', 23, 29, 'عیسی زیاته کړه: «ای منافقانو د شریعت عالمانو او فریسیانو! افسوس دې وي ستاسو په حال، ځکه چې تاسو د پیغمبرانو زیارتونه جوړوئ او د نېکو خلکو قبرونه ښکلي کوئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_29.mp3', '', 1761754199, 1761754199),
(31033, 'Matthew 23:30', 'Matthew', 23, 30, 'او وایئ: ‹که چېرې مونږ د خپلو نیکونو په زمانه کې ژوندي وای نو د هغوی سره به د پیغمبرانو په قتل کې شریک شوي نه وای.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_30.mp3', '', 1761754199, 1761754199),
(31034, 'Matthew 23:31', 'Matthew', 23, 31, 'نو تاسو په خپلو ځانونو باندې شاهدي ورکوئ چې تاسو د هغو خلکو اولاده یئ چې پیغمبران یې قتل کړي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_31.mp3', '', 1761754199, 1761754199),
(31035, 'Matthew 23:32', 'Matthew', 23, 32, 'نو لاړ شئ او هغه کارونه چې ستاسو نیکونو پیل کړي وو، سرته ورسوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_32.mp3', '', 1761754199, 1761754199),
(31036, 'Matthew 23:33', 'Matthew', 23, 33, 'ای مارانو او د مارانو بچیانو! تاسو به د دوزخ له سزا څخه څنګه خلاص شئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_33.mp3', '', 1761754199, 1761754199),
(31037, 'Matthew 23:34', 'Matthew', 23, 34, 'نو له دې امله زه تاسو ته پیغمبران، هوښیار خلک او د شریعت عالمان درلېږم، خو ځینې به تاسو مړه کړئ، ځینې به په صلیب راځوړند کړئ او ځینې به په کنیسو کې په دورو ووهئ او ښار په ښار به ورپسې ګرځئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_34.mp3', '', 1761754199, 1761754199),
(31038, 'Matthew 23:35', 'Matthew', 23, 35, 'نو له دې امله د ټولو نېکو خلکو وینې چې په ځمکه توییږي، خون به یې ستاسو په غاړه وي، د بې‌ګناه هابیل څخه نیولې د برخیا د زوی زکریا پورې چې هغه مو د خدای د کور او د قربانۍ د ځای ترمنځ وواژه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_35.mp3', '', 1761754199, 1761754199),
(31039, 'Matthew 23:36', 'Matthew', 23, 36, 'په یقین سره زه تاسو ته دا وایم چې د دې ټولو کارونو سزا به د دې زمانې خلکو ته ورکول کیږي.» د اورشلیم دپاره د عیسی خفګان (لوقا ۱۳‏:‌۳۴‌‏-‌۳۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_36.mp3', '', 1761754199, 1761754199),
(31040, 'Matthew 23:37', 'Matthew', 23, 37, 'عیسی زیاته کړه: «ای اورشلیمه، ای اورشلیمه! ای هغه ښاره چې پیغمبران وژنې او کوم کسان چې د خدای له خوا درلېږل کیږي هغه سنګساروې! ما څو څو ځلې وغوښتل چې ستا خلک داسې سره راټول کړم لکه څنګه چې چرګه خپل بچي د خپلو وزرونو لاندې سره راټولوي، خو تا ونه غوښتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_37.mp3', '', 1761754199, 1761754199),
(31041, 'Matthew 23:38', 'Matthew', 23, 38, 'ګوره، ستاسو کور تاسو ته خالي پرېښودل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_38.mp3', '', 1761754199, 1761754199),
(31042, 'Matthew 23:39', 'Matthew', 23, 39, 'ځکه چې زه تاسو ته وایم چې بیا به هېڅکله ما ونه وینئ، ترڅو دا ونه وایئ: ‹مبارک دی هغه څوک چې د څښتن په نوم راځي.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew23_verse_39.mp3', '', 1761754199, 1761754199),
(31043, 'Luke 2:1', 'Luke', 2, 1, 'په هغه وخت کې امپراتور اګوستوس د روم په ټوله امپراتورۍ کې د سرشمېرنې په خاطر یو فرمان جاري کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_1.mp3', '', 1761754199, 1761754199),
(31044, 'Luke 2:2', 'Luke', 2, 2, 'دا لومړنۍ سرشمېرنه وه چې د سوریې د والي کرینوس په وخت کې وشوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_2.mp3', '', 1761754199, 1761754199),
(31045, 'Luke 2:3', 'Luke', 2, 3, 'هرڅوک خپل ښار ته لاړ چې خپل نوم ولیکي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_3.mp3', '', 1761754199, 1761754199),
(31046, 'Luke 2:4', 'Luke', 2, 4, 'نو یوسف هم د جلیل د ناصرې د ښار څخه د یهودیې د ولایت د بیت‌لحم ښار ته چې د داود پاچا د زېږېدنې ځای ؤ لاړ، ځکه چې هغه د داود د کورنۍ څخه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_4.mp3', '', 1761754199, 1761754199),
(31047, 'Luke 2:5', 'Luke', 2, 5, 'یوسف د مریم سره چې کوژدنه یې وه او امیدواره وه، د نوم لیکنې دپاره هلته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_5.mp3', '', 1761754199, 1761754199),
(31048, 'Luke 2:6', 'Luke', 2, 6, 'او کله چې هغوی په بیت‌لحم کې وو د هغې د ماشوم د زېږېدلو وخت راورسېد.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_6.mp3', '', 1761754199, 1761754199),
(31049, 'Luke 2:7', 'Luke', 2, 7, 'هغې خپل لومړنی اولاد چې هلک ؤ، وزېږاوه. هغه یې په اورني کې تاو کړ او په آخور کې یې کېښود، ځکه چې په مسافرخانه کې د هغوی دپاره ځای نه ؤ. شپنو ته د فرښتو زېری', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_7.mp3', '', 1761754199, 1761754199),
(31050, 'Luke 2:8', 'Luke', 2, 8, 'په هغې سیمه کې څو شپانه وو چې په شاوخوا ځمکو کې اوسېدل او د شپې به یې په خپلو رمو باندې پام کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_8.mp3', '', 1761754199, 1761754199),
(31051, 'Luke 2:9', 'Luke', 2, 9, 'د څښتن فرښته هغوی ته ښکاره شوه او د څښتن د جلال رڼا په هغوی باندې وځلېدله. هغوی سخت ووېرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_9.mp3', '', 1761754199, 1761754199),
(31052, 'Luke 2:10', 'Luke', 2, 10, 'خو فرښتې هغوی ته وویل: «مه وېرېږئ، ما تاسو ته یو زېری راوړی چې د ټولو خلکو دپاره به یوه لویه خوشحالي وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_10.mp3', '', 1761754199, 1761754199),
(31053, 'Luke 2:11', 'Luke', 2, 11, 'همدا نن د داود په ښار کې ستاسو دپاره یو خلاصوونکی زېږېدلی دی چې هغه مسیح او څښتن دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_11.mp3', '', 1761754199, 1761754199),
(31054, 'Luke 2:12', 'Luke', 2, 12, 'او ستاسو دپاره به دا نښه وي چې یو ماشوم به پیدا کړئ چې په اورني کې به تاو شوی وي او په آخور کې به پروت وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_12.mp3', '', 1761754199, 1761754199),
(31055, 'Luke 2:13', 'Luke', 2, 13, 'ناڅاپه د هغې فرښتې سره یو لوی اسماني لښکر راښکاره شو چې د خدای دا ثنا یې ویله:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_13.mp3', '', 1761754199, 1761754199),
(31056, 'Luke 2:14', 'Luke', 2, 14, '«خدای ته دې وي جلال په لوړو اسمانونو کې او سوله او سلامتي دې وي په ځمکه باندې په هغو خلکو باندې چې ترې راضي دی هغه»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_14.mp3', '', 1761754199, 1761754199),
(31057, 'Luke 2:15', 'Luke', 2, 15, 'کله چې فرښتې هغوی پرېښودل او بېرته اسمان ته لاړې، نو شپنو یو بل ته سره وویل: «راځئ چې بیت‌لحم ته لاړ شو او هغه څه چې پېښ شوي دي او څښتن مونږ د هغې څخه خبر کړي یو، ووینو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_15.mp3', '', 1761754199, 1761754199),
(31058, 'Luke 2:16', 'Luke', 2, 16, 'نو هغوی په منډه لاړل، مریم او یوسف یې پیدا کړل او ویې لیدل چې ماشوم په آخور کې پروت دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_16.mp3', '', 1761754199, 1761754199),
(31059, 'Luke 2:17', 'Luke', 2, 17, 'کله چې شپنو هغه ماشوم ولیده، نو څه چې یې د هغه په هکله اورېدلي وو، ټول یې خبر کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke2_verse_17.mp3', '', 1761754199, 1761754199),
