(31102, 'Acts 19:8', 'Acts', 19, 8, 'پولوس تر درې میاشتو پورې کنیسې ته تللو او په زړورتیا سره به یې د خلکو سره خبرې کولې او د خدای د پاچاهۍ په هکله به یې هغوی ته دلیل ویلو او بحث به یې کاوه چې هغوی قانع کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_8.mp3', '', 1761754199, 1761754199),
(31103, 'Acts 19:9', 'Acts', 19, 9, 'خو د هغوی څخه ځینې سرزورو خلکو ایمان نه راوړلو او د کنیسې د خلکو په مخکې به یې د څښتن عیسی مسیح لارې ته بد ویل. نو پولوس له هغوی څخه لاړ او شاګردان یې له ځان سره بوتلل او هره ورځ به یې د تیرانوس د غونډو په تالار کې بحثونه کول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_9.mp3', '', 1761754199, 1761754199),
(31104, 'Acts 19:10', 'Acts', 19, 10, 'دا کار تر دوو کالو پورې روان ؤ، ترڅو د اسیا د ولایت ټولو اوسېدونکو یعنې یهودیانو او یونانیانو دواړو د څښتن عیسی پیغام واورېد. د اسکیوا زامن', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_10.mp3', '', 1761754199, 1761754199),
(31105, 'Acts 19:11', 'Acts', 19, 11, 'خدای به د پولوس په وسیله لویې لویې معجزې ښودلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_11.mp3', '', 1761754199, 1761754199),
(31106, 'Acts 19:12', 'Acts', 19, 12, 'خلکو به هغه دستمالونه او پېشبندونه چې د پولوس په بدن باندې وهل شوي وو، وړل او هغه به یې د ناروغانو په بدن باندې وهل او هغوی به روغېدل او پېریان به ورڅخه وتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_12.mp3', '', 1761754199, 1761754199),
(31107, 'Acts 19:13', 'Acts', 19, 13, 'ځینو یهودیانو چې یوځای او بل ځای به ګرځېدل، کوښښ کاوه چې د څښتن عیسی په نوم پېریان وباسي. هغوی به پېریانو ته ویل: «زه د هغه عیسی په نوم چې پولوس یې وعظ کوي، امر کوم چې راووځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_13.mp3', '', 1761754199, 1761754199),
(31108, 'Acts 19:14', 'Acts', 19, 14, 'د یهودي لوی کاهن اسکیوا اووه زامنو به دا کار کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_14.mp3', '', 1761754199, 1761754199),
(31109, 'Acts 19:15', 'Acts', 19, 15, 'خو یوه ورځ پېري هغوی ته ځواب ورکړ: «زه عیسی پېژنم او د پولوس په هکله مې هم اورېدلي دي، خو تاسو څوک یئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_15.mp3', '', 1761754199, 1761754199),
(31110, 'Acts 19:16', 'Acts', 19, 16, 'نو بیا هغه پېریانو نیولي سړي په هغوی ورټوپ کړ او هغوی ټول یې تر‌پښو لاندې کړل او دومره یې ووهل چې د هغه کور څخه لوڅ او ژوبل شوي وتښتېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_16.mp3', '', 1761754199, 1761754199);